    int root = x;
    while (parent[root] != root)
        root = parent[root];

    while (parent[x] != x) {
        int next = parent[x];
        parent[x] = root;
        x = next;
    }
    return root;
}

static ll merge_components(
    int a, int b,
    int *parent, int *component_size, int *left_bound, int *right_bound,
    int *head, int *tail, int *next_position,
    int *root_x, int *root_y,
    Node *tree_x, Node *tree_y,
    ll *x_value, ll *y_value, ll *height, ll k
) {
    a = find_root(parent, a);
    b = find_root(parent, b);
    if (a == b)
        return 0;

    int left_component = left_bound[a] < left_bound[b] ? a : b;
    int right_component = left_component == a ? b : a;

    int big, small;
    if (component_size[a] >= component_size[b]) {
        big = a;
        small = b;
    } else {
        big = b;
        small = a;
    }

    int small_is_left = (small == left_component);
    ll added_pairs = 0;

    /* Count pairs between the two components before inserting either side. */
    for (int p = head[small]; p != 0; p = next_position[p]) {
        if (small_is_left) {
            ll target_x = x_value[p] + k;
            int total_x = count_value_le(tree_x, root_x[big], target_x)
                        - count_value_lt(tree_x, root_x[big], target_x);
            int less_x = count_value_height_lt(tree_x, root_x[big],
                                               target_x, height[p]);
            added_pairs += (ll)(total_x - less_x);

            ll target_y = y_value[p] + k;
            added_pairs += count_value_height_lt(tree_y, root_y[big],
                                                 target_y, height[p]);
        } else {
            ll target_x = x_value[p] - k;
            added_pairs += count_value_height_lt(tree_x, root_x[big],
                                                 target_x, height[p] + 1);

            ll target_y = y_value[p] - k;
            int total_y = count_value_le(tree_y, root_y[big], target_y)
                        - count_value_lt(tree_y, root_y[big], target_y);
            int less_y = count_value_height_lt(tree_y, root_y[big],
                                               target_y, height[p] + 1);
            added_pairs += (ll)(total_y - less_y);
        }
    }

    /* Move the smaller component's points into the larger component's treaps. */
    for (int p = head[small]; p != 0; p = next_position[p]) {
        tree_x[p].left = tree_x[p].right = 0;
        tree_x[p].size = 1;
        root_x[big] = treap_insert(tree_x, root_x[big], p);

        tree_y[p].left = tree_y[p].right = 0;
        tree_y[p].size = 1;
        root_y[big] = treap_insert(tree_y, root_y[big], p);
    }

    next_position[tail[big]] = head[small];
    tail[big] = tail[small];

    parent[small] = big;
    component_size[big] += component_size[small];
    if (left_bound[small] < left_bound[big])
        left_bound[big] = left_bound[small];
    if (right_bound[small] > right_bound[big])
        right_bound[big] = right_bound[small];

    return added_pairs;
}

int main(void) {
    int n, q;
    ll k;

    if (scanf("%d %d %lld", &n, &q, &k) != 3)
        return 0;

    ll *height = (ll *)malloc((size_t)(n + 1) * sizeof(ll));
    ll *x_value = (ll *)malloc((size_t)(n + 1) * sizeof(ll));
    ll *y_value = (ll *)malloc((size_t)(n + 1) * sizeof(ll));
    int *deletions = (int *)malloc((size_t)(q + 1) * sizeof(int));
    int *active = (int *)calloc((size_t)(n + 1), sizeof(int));

    int *parent = (int *)malloc((size_t)(n + 1) * sizeof(int));
    int *component_size = (int *)malloc((size_t)(n + 1) * sizeof(int));
    int *left_bound = (int *)malloc((size_t)(n + 1) * sizeof(int));
    int *right_bound = (int *)malloc((size_t)(n + 1) * sizeof(int));
    int *head = (int *)malloc((size_t)(n + 1) * sizeof(int));
    int *tail = (int *)malloc((size_t)(n + 1) * sizeof(int));
    int *next_position = (int *)calloc((size_t)(n + 1), sizeof(int));
    int *root_x = (int *)calloc((size_t)(n + 1), sizeof(int));
    int *root_y = (int *)calloc((size_t)(n + 1), sizeof(int));

    Node *tree_x = (Node *)calloc((size_t)(n + 1), sizeof(Node));
    Node *tree_y = (Node *)calloc((size_t)(n + 1), sizeof(Node));

    for (int i = 1; i <= n; i++) {
        scanf("%lld", &height[i]);
        x_value[i] = (ll)i + height[i];
        y_value[i] = (ll)i - height[i];
    }

    for (int t = 1; t <= q; t++) {
        scanf("%d", &deletions[t]);
        active[deletions[t]] = 0;
    }

    for (int i = 1; i <= n; i++) {
        parent[i] = i;
        component_size[i] = 1;
        left_bound[i] = right_bound[i] = i;

        tree_x[i].value = x_value[i];
        tree_x[i].height = height[i];
        tree_x[i].index = i;
        tree_x[i].size = 1;
        tree_x[i].priority = splitmix64((ull)i);

        tree_y[i].value = y_value[i];
        tree_y[i].height = height[i];
        tree_y[i].index = i;
        tree_y[i].size = 1;
        tree_y[i].priority = splitmix64((ull)i + 0x123456789abcdefULL);
    }

    /* Mark all positions that remain after the Q forward deletions. */
    for (int i = 1; i <= n; i++)
        active[i] = 1;
    for (int t = 1; t <= q; t++)
        active[deletions[t]] = 0;

    for (int i = 1; i <= n; i++) {
        if (active[i]) {
            head[i] = tail[i] = i;
            root_x[i] = i;
            root_y[i] = i;
        }
    }

    ll answer = 0;

    /* Build the components present after all deletions. */
    for (int i = 2; i <= n; i++) {
        if (active[i] && active[i - 1]) {
            answer += merge_components(
                i - 1, i, parent, component_size, left_bound, right_bound,
                head, tail, next_position, root_x, root_y, tree_x, tree_y,
                x_value, y_value, height, k
            );
        }
    }

    ll *answers = (ll *)malloc((size_t)(q + 1) * sizeof(ll));
    answers[q] = answer;

    /* Undo deletions in reverse order, merging adjacent components. */
    for (int t = q; t >= 1; t--) {
        int p = deletions[t];

        if (!active[p]) {
            active[p] = 1;
            parent[p] = p;
            component_size[p] = 1;
            left_bound[p] = right_bound[p] = p;
            head[p] = tail[p] = p;
            next_position[p] = 0;

            tree_x[p].left = tree_x[p].right = 0;
            tree_x[p].size = 1;
            tree_y[p].left = tree_y[p].right = 0;
            tree_y[p].size = 1;

            root_x[p] = p;
            root_y[p] = p;

            if (p > 1 && active[p - 1]) {
                answer += merge_components(
                    p - 1, p, parent, component_size, left_bound, right_bound,
                    head, tail, next_position, root_x, root_y, tree_x, tree_y,
                    x_value, y_value, height, k
                );
            }
            if (p < n && active[p + 1]) {
                answer += merge_components(
                    p, p + 1, parent, component_size, left_bound, right_bound,
                    head, tail, next_position, root_x, root_y, tree_x, tree_y,
                    x_value, y_value, height, k
                );
            }
        }

        answers[t - 1] = answer;
    }

    for (int t = 0; t <= q; t++)
        printf("%lld\n", answers[t]);

    free(height);
    free(x_value);
    free(y_value);
    free(deletions);
    free(active);
    free(parent);
    free(component_size);
    free(left_bound);
    free(right_bound);
    free(head);
    free(tail);
    free(next_position);
    free(root_x);
    free(root_y);
    free(tree_x);
    free(tree_y);
    free(answers);

    return 0;
}
